from pathlib import Path
import sys,json,subprocess,numpy as np
R=Path(__file__).resolve().parents[1];v=R/sys.argv[1];tag=sys.argv[2] if len(sys.argv)>2 else 'final'
p=json.loads(subprocess.check_output(['ffprobe','-v','error','-count_frames','-show_streams','-show_format','-of','json',str(v)]));video=next(s for s in p['streams'] if s['codec_type']=='video');audio=next(s for s in p['streams'] if s['codec_type']=='audio')
assert video['width']==1080 and video['height']==1920 and video['r_frame_rate']=='30/1' and video['codec_name']=='h264' and int(video['nb_read_frames'])==2580;assert abs(float(p['format']['duration'])-86)<.001;assert audio['codec_name']=='aac' and audio['sample_rate']=='48000' and audio['channels']==2
(R/'reports'/f'{tag}-encoding.json').write_text(json.dumps(p,indent=2));q=subprocess.run(['ffmpeg','-v','error','-i',str(v),'-f','null','-'],capture_output=True,text=True);assert q.returncode==0;(R/'reports'/f'{tag}-decode.txt').write_text('Full FFmpeg decode exit=0\n'+q.stderr)
b=subprocess.check_output(['ffmpeg','-v','error','-i',str(v),'-vf','scale=54:96','-pix_fmt','rgb24','-f','rawvideo','pipe:1']);frames=np.frombuffer(b,np.uint8).reshape(-1,96,54,3);assert len(frames)==2580;means=frames.mean((1,2,3));diff=np.abs(np.diff(frames.astype(float),axis=0)).mean((1,2,3));assert means.min()>3
content={'decoded_frames':len(frames),'minimum_frame_mean_255':float(means.min()),'identical_adjacent_frames':int((diff==0).sum()),'note':'Pixel changes do not certify artistic motion quality.'};(R/'reports'/f'{tag}-content.json').write_text(json.dumps(content,indent=2))
a=subprocess.run(['ffmpeg','-v','info','-i',str(v),'-vn','-af','loudnorm=I=-16:TP=-2:LRA=8:print_format=json','-f','null','-'],capture_output=True,text=True,check=True);m=json.JSONDecoder().raw_decode(a.stderr[a.stderr.rfind('{'):])[0];(R/'reports'/f'{tag}-audio-meter.json').write_text(json.dumps(m,indent=2));print(json.dumps({'file':str(v),'duration':p['format']['duration'],'frames':video['nb_read_frames'],'audio_lufs':m['input_i'],'audio_true_peak':m['input_tp'],**content},indent=2))
